from pathlib import Path
p=Path('geo-monitor-deploy/creation/panel.html');s=p.read_text('utf8')
s=s.replace('先选素材，再生成文章；通过审稿的成稿会出现在下方，可直接下载 Word。','导入产品知识库 → 配置每日问题与时间 → 自动采集、分析、仿写和审稿 → 下载 Word。')
start=s.index('<nav class="row nav">');end=s.index('</nav>',start)+6
s=s[:start]+'''<nav class="row nav"><a href="#knowledge">① 产品知识库</a><a href="#dailyPlan">② 每日任务配置</a><a href="#dailyTasks">③ 当天任务</a><a href="#outputs">④ 下载成稿</a></nav>'''+s[end:]
start=s.index('<section id="create">');end=s.index('<dialog id="preview">',start)
old=s[start:end];manual_end=old.index('<section id="tasks">');manual=old[:manual_end]
legacy_start=old.index('<section id="tasks">');legacy_end=old.index('<section id="materials">')
legacy=old[legacy_start:legacy_end].replace('<h2>创作任务进度</h2>','<h2>单项创作执行详情</h2>')
new='''<section id="knowledge"><div class="step">第一步 · 导入产品资料</div><h2>产品知识库</h2><p class="muted">每个产品保存自己的知识库。导入 Word 后先查看提取内容，确认产品名称和事实，再保存。执行中的任务保留当时的知识库版本。</p><div class="row"><select id="kbSelect" style="width:auto;max-width:70%" onchange="loadKnowledge(this.value)"></select><button id="kbNew" onclick="loadKnowledge('')">新增产品</button></div><div class="grid"><div><label for="kbWord">导入产品知识库 Word</label><input id="kbWord" type="file" accept=".docx"><div class="row" style="margin-top:10px"><button id="kbImport" class="primary">读取 Word 内容</button><small>.docx，最大5MB，支持正文和表格文字</small></div><p id="kbSource" class="muted"></p><label for="kbName">产品名称</label><input id="kbName" oninput="kbDirty=true"><label for="kbBrand">品牌</label><input id="kbBrand" oninput="kbDirty=true"><label for="kbAudience">目标读者</label><input id="kbAudience" oninput="kbDirty=true"></div><div><label for="kbFacts">知识库内容（确认后保存，每行一条）</label><textarea id="kbFacts" style="min-height:310px" oninput="kbDirty=true" placeholder="导入Word后会在这里展示文字，也可手动填写产品事实。"></textarea><small>保留原Word和导入记录。这里是你提供的产品资料，生成时继续接受原有事实、证据和审稿检查。</small><button id="kbSave" class="primary" style="margin-top:12px">保存产品知识库</button></div></div></section>
<section id="dailyPlan"><div class="step">第二步 · 配置自动执行</div><h2>每日创作任务配置</h2><p class="muted">一个配置对应一个产品，每天生成一项任务。到采集时间开始跑问题；到分析时间且全部素材完整后，自动分析、仿写、审稿并生成 Word。</p><div class="row"><select id="planSelect" style="width:auto;max-width:70%" onchange="loadPlan(this.value)"></select><button id="planNew" onclick="loadPlan('')">新增每日任务</button></div><div class="grid"><div><label for="planProduct">使用哪个产品知识库</label><select id="planProduct" onchange="planDirty=true"></select><label for="planStart">首次执行日期</label><input id="planStart" type="date" onchange="planDirty=true"><div class="grid"><div><label for="planCapture">每天开始采集（北京时间）</label><input id="planCapture" type="time" onchange="planDirty=true"></div><div><label for="planWriting">分析仿写最早开始（北京时间）</label><input id="planWriting" type="time" onchange="planDirty=true"></div></div><label>采集模型</label><div id="planChannels"></div><div class="grid"><div><label for="planRounds">每题每个模型采集轮数</label><input id="planRounds" type="number" min="1" max="10" value="1" oninput="planDirty=true"></div><div><label for="planCount">每个问题每类最多生成篇数</label><input id="planCount" type="number" min="1" max="10" value="1" oninput="planDirty=true"></div></div><label class="row"><input id="planEnabled" type="checkbox" onchange="planDirty=true">启用每天自动采集、分析和创作</label></div><div><label for="planQuestions">监测与创作问题（每行一题）</label><textarea id="planQuestions" style="min-height:340px" oninput="planDirty=true"></textarea><p id="planHint" class="muted"></p></div></div><p class="hint">采集素材只供创作中心使用，不进入主 GEO。主监测占用账号时等待；DeepSeek 提问至少间隔10分钟，百度卡片先于文心卡片。素材未齐时继续等待，达到分析时间也不会使用残缺素材。已开始的当日任务保留原配置，新设置用于后续任务。</p><div class="row"><button id="planSave" class="primary">保存每日任务配置</button><button id="planEnable" class="primary">保存并启用每日任务</button><button id="balance">查看 API 余额</button><span id="balanceText" class="muted"></span></div><p id="studioLimits" class="budget"></p></section>
<section id="dailyTasks"><div class="step">第三步 · 每天的任务在这里</div><div class="row between"><h2>当天任务与进度</h2><a href="#outputs">查看最终成稿 ↓</a></div><p id="dailyDateHint" class="muted"></p><div id="dailyMetrics" class="metrics"></div><div id="dailyCards"></div></section>
'''
# Existing one-off material reuse stays available but is no longer the primary workflow.
manual=manual.replace('<button id="balance">查看 API 余额</button><span id="balanceText" class="muted"></span>','')
manual=manual.replace('<button id="balance">查看 API 余额</button>','').replace('<span id="balanceText" class="muted"></span>','')
s=s[:start]+new+'<details style="margin:20px 0"><summary>高级操作：用已有素材临时创作，或查看历史单项任务</summary>'+manual+legacy+'</details>'+s[end:]
# Put configuration and daily dashboard before the output library.
output_start=s.index('<section id="outputs">');knowledge_start=s.index('<section id="knowledge">');outputs=s[output_start:knowledge_start]
s=s[:output_start]+s[knowledge_start:];insert=s.index('<details style="margin:20px 0">');s=s[:insert]+outputs+s[insert:]
s=s.replace("const API='/api/';let csrf", "const API='/api/';let kbDirty=false,planDirty=false,kbId='',planId='',importId='',studioLoaded=false;let csrf")
s=s.replace("sessionStorage.setItem('geo.creation.pending',JSON.stringify(item));", "try{if(item.payload.length<600000)sessionStorage.setItem('geo.creation.pending',JSON.stringify(item))}catch{};")
s=s.replace("for(const a of [...all,...data.jobs])", "for(const a of [...all,...data.jobs,...(data.studio?.daily_tasks||[])])")
s=s.replace('renderJobs();buttons()}\nfunction todayFilter', 'renderJobs();renderDailyTasks();buttons()}\nfunction todayFilter')
s=s.replace('renderFilterOptions();renderLibrary();renderJobs();renderMaterials();buttons()', 'renderFilterOptions();renderLibrary();renderJobs();renderStudio();buttons()')
s=s.replace("if(name==='materials_settings')materialDirty=false;", "if(name==='materials_settings')materialDirty=false;if(['kb_import','kb_save','plan_save','day_pause','day_resume'].includes(name))studioResult(name,result.result);")
# The removed old standalone capture controls must not be bound.
start=s.index("$('materialSave').onclick=");end=s.index("$('retryAction').onclick=",start)
s=s[:start]+s[end:]
insert=s.index("(async()=>{await refresh();")
js='''
const studioStates={scheduled:'等待定时',capture_only:'已保留定时采集，自动创作未启用',not_enabled:'尚未启用',collecting:'正在采集问题',waiting_for_geo:'等待主GEO让出账号',waiting_login:'需要登录或人工验证',waiting_writing:'素材已齐，等待分析时间',creating:'正在分析、仿写和审稿',complete:'已完成',paused:'已手动暂停',needs_attention:'需要处理'};
function loadKnowledge(id){kbId=id||'';importId='';kbDirty=false;const kb=(data.studio?.products||[]).find(p=>p.product_id===kbId),p=kb?.product||{};$('kbSelect').value=kbId;$('kbName').value=p.name||'';$('kbBrand').value=p.brand||'';$('kbAudience').value=p.audience||'';$('kbFacts').value=(p.facts||[]).map(f=>f.text).join('\\n');$('kbSource').textContent=kb?.word_source?.filename?'已导入：'+kb.word_source.filename:kb?'已保留原项目产品资料，可更新或重新导入 Word':'选择 Word 文件，读取并确认后保存新产品'}
function loadPlan(id){planId=id||'';planDirty=false;const p=(data.studio?.plans||[]).find(p=>p.plan_id===planId)||{};$('planSelect').value=planId;$('planProduct').value=p.product_id||kbId||data.studio?.products[0]?.product_id||'';$('planStart').value=p.start_date||data.studio?.today||'';$('planCapture').value=p.capture_time||'01:00';$('planWriting').value=p.writing_time||'04:00';$('planRounds').value=p.rounds||1;$('planCount').value=p.max_per_category||1;$('planEnabled').checked=!!p.enabled;$('planQuestions').value=(p.questions||data.materials?.settings.questions||[]).join('\\n');$('planChannels').innerHTML=[['deepseek','DeepSeek'],['baidu_ai','百度卡片'],['wenxin_card','文心卡片']].map(([id,name])=>`<label style="display:inline-flex;margin-right:12px;gap:6px"><input type="checkbox" name="planChannel" value="${id}" ${(p.channels||['deepseek','baidu_ai','wenxin_card']).includes(id)?'checked':''} onchange="planDirty=true">${name}</label>`).join('');$('planHint').textContent=p.legacy_capture&&!p.enabled?'原01:00独立采集已保留。请选择分析时间，再点击“保存并启用每日任务”接通自动分析与创作。':'确认产品、问题、采集时间与分析时间后保存；素材未完成时自动等待。'}
function renderStudio(){const st=data.studio;if(!st)return;const selectedKB=kbId,selectedPlan=planId;$('kbSelect').innerHTML='<option value="">新增产品知识库</option>'+st.products.map(k=>`<option value="${k.product_id}">${escape(k.product.name)}</option>`).join('');$('planProduct').innerHTML=st.products.map(k=>`<option value="${k.product_id}">${escape(k.product.name)}</option>`).join('');$('planSelect').innerHTML='<option value="">新增每日任务</option>'+st.plans.map(p=>`<option value="${p.plan_id}">${escape(p.product.name)} · ${p.capture_time}采集 / ${p.writing_time}分析</option>`).join('');if(!studioLoaded){studioLoaded=true;loadKnowledge(st.products[0]?.product_id||'');loadPlan(st.plans[0]?.plan_id||'')}else{const kp=selectedKB;$('kbSelect').value=kp;if(!kbDirty)loadKnowledge(kp);const pp=$('planProduct').dataset.selected||'';$('planSelect').value=selectedPlan;if(!planDirty)loadPlan(selectedPlan);else if(pp)$('planProduct').value=pp}$('studioLimits').textContent='费用沿用原预算：单篇含共享分析 ¥'+data.settings.article_budget_cny+'，每日共享 ¥'+data.settings.daily_budget_cny+'。达到预算或遇到审稿/API异常会保留进度并显示原因；成稿不会自动发布。';renderDailyTasks()}
function renderDailyTasks(){const st=data?.studio;if(!st)return;const date=$('dateFilter').value||st.today,rows=st.daily_tasks.filter(t=>t.date===date&&(!$('productFilter').value||t.product.id===$('productFilter').value));$('dailyDateHint').textContent='任务日期：'+date+'（北京时间） · 与成稿区产品、日期筛选联动；默认查看今天。';const active=rows.filter(t=>['collecting','creating'].includes(t.status)).length,done=rows.filter(t=>t.status==='complete').length,attention=rows.filter(t=>['needs_attention','waiting_login'].includes(t.status)).length;$('dailyMetrics').innerHTML=[['当日任务',rows.length],['正在执行',active],['已完成 / 需处理',done+' / '+attention]].map(([k,v])=>`<div class="metric"><small>${k}</small><b>${v}</b></div>`).join('');$('dailyCards').innerHTML=rows.length?rows.map(t=>`<article class="job"><div class="row between"><h3>${escape(t.product.name)}</h3><span class="badge">${escape(studioStates[t.status]||t.status)}</span></div><small>${escape(t.date)} · ${t.questions}个问题 · ${t.capture_time}采集 / ${t.writing_time}起分析仿写</small><div class="material-progress">${t.progress.map(m=>`<div class="card"><small>${escape(m.name)}</small><b>${m.completed} / ${t.target_per_model}</b><small>${m.blocked.kind?'需要登录或验证':'问题采集进度'}</small></div>`).join('')}</div><p><b>分析创作 ${t.writing_complete} / ${t.questions} 项已完成 · ${t.articles} 篇成稿可下载</b></p><p class="muted">${escape(Object.entries(t.stages||{}).map(([k,n])=>{const [stage,status]=k.split(':');return(stages[stage]||stage)+' '+n+'项'+({accepted:'已通过',pending:'待执行',running:'执行中',revision_requested:'待修订',failed:'需处理'}[status]||status)}).join(' · '))}</p>${t.error?`<p class="error">${escape(t.error)}</p>`:''}<div class="row">${!['complete','not_enabled','capture_only'].includes(t.status)?`<button data-day-action="${t.status==='paused'||t.status==='needs_attention'||t.status==='waiting_login'?'day_resume':'day_pause'}" data-plan="${t.plan_id}" data-date="${t.date}">${t.status==='paused'?'继续当日任务':t.status==='needs_attention'||t.status==='waiting_login'?'重新检查并继续':'暂停当日任务'}</button>`:''}<a class="button" href="#outputs" data-show-day="${t.date}" data-product="${t.product.id}">查看该产品当天成稿</a><a class="button" href="#dailyPlan" data-edit-plan="${t.plan_id}">修改任务配置</a></div></article>`).join(''):'<div class="empty">这一天没有每日任务。请先保存产品知识库，再配置并启用每日任务。</div>';document.querySelectorAll('[data-day-action]').forEach(b=>b.onclick=()=>act(b.dataset.dayAction,{plan_id:b.dataset.plan,date:b.dataset.date}));document.querySelectorAll('[data-show-day]').forEach(a=>a.onclick=()=>{$('dateFilter').value=a.dataset.showDay;$('productFilter').value=a.dataset.product;applyFilters()});document.querySelectorAll('[data-edit-plan]').forEach(a=>a.onclick=()=>loadPlan(a.dataset.editPlan))}
function studioResult(name,r){if(name==='kb_import'){importId=r.import_id;kbDirty=true;$('kbFacts').value=r.text;$('kbSource').textContent='已读取 '+r.filename+'，共'+r.paragraphs+'段，请确认后保存产品知识库'}if(name==='kb_save'){kbId=r.product_id;kbDirty=false;importId=''}if(name==='plan_save'){planId=r.plan_id;planDirty=false}}
function planPayload(enable){return{...(planId?{plan_id:planId}:{}),product_id:$('planProduct').value,questions:$('planQuestions').value.split('\\n').map(s=>s.trim()).filter(Boolean),channels:[...document.querySelectorAll('[name=planChannel]:checked')].map(c=>c.value),capture_time:$('planCapture').value,writing_time:$('planWriting').value,start_date:$('planStart').value,rounds:Number($('planRounds').value),max_per_category:Number($('planCount').value),enabled:enable??$('planEnabled').checked}}
$('planProduct').addEventListener('change',()=>{$('planProduct').dataset.selected=$('planProduct').value});
$('kbImport').onclick=async()=>{const file=$('kbWord').files[0];if(!file){message('请先选择Word文件',true);return}if(!file.name.toLowerCase().endsWith('.docx')||file.size>5*1024*1024){message('请选择5MB以内的.docx文件',true);return}const reader=new FileReader();reader.onload=()=>act('kb_import',{filename:file.name,content_base64:String(reader.result).split(',')[1]});reader.readAsDataURL(file)};
$('kbSave').onclick=()=>act('kb_save',{...(kbId?{product_id:kbId}:{}),...(importId?{import_id:importId}:{}),name:$('kbName').value,brand:$('kbBrand').value,audience:$('kbAudience').value,facts:$('kbFacts').value.split('\\n').map(v=>v.trim()).filter(Boolean)});
$('planSave').onclick=()=>act('plan_save',planPayload());$('planEnable').onclick=()=>act('plan_save',planPayload(true));
'''
s=s[:insert]+js+s[insert:]
# Older no-longer-visible materials renderer is retained for compatibility but never called.
p.write_text(s,encoding='utf8')
